 preserve={'mov','movzx','movsx','movsxd','lea','push','pop','nop','movaps','movups','movdqa','movdqu','movq','movd','pshufd','punpcklqdq','pxor','xorps','xorps','bswap','xchg','not','cdqe','cqo','cld','std','endbr64','rdtsc','rdtscp','cpuid','pushfq','movapd','movupd','movsd','movss','xorpd','andpd','orpd','pshufb','pshuflw','pshufhw','unpcklpd','unpckhpd','punpckldq','punpckhdq'}
 while pending:
  ea,flags=pending.pop()
