    o0,o1=ii.ops[0],ii.ops[1]
    if o0.type==ida_ua.o_reg and o1.type==ida_ua.o_reg and o0.reg==o1.reg:nf=1<<18

   if m in ('stc','clc','cmc'):
    nf=0
    for bits in range(32):
     if not flags&(1<<bits):continue
     value=(bits|1) if m=='stc' else (bits&~1) if m=='clc' else (bits^1)
