body_overlap_journals=[]
def eliminate_ebff_overlaps(ix):
 a,b=bodies[ix]['body'],bodies[ix]['end']
 graph=domain_flag_graph_v3(a,b);nn=graph[0]
 assert not any(graph[k] for k in (2,3,4))
 sp=sorted((ea,ea+ins.size) for ea,ins in nn.items())
 overlaps=[(x,y,c,d) for (x,y),(c,d) in zip(sp,sp[1:]) if y>c]
 changes=[]
 for x,y,c,d in overlaps:
  assert c==x+1 and y==x+2 and ida_bytes.get_bytes(x,2)==b'\xeb\xff'
  assert nn[x].get_canon_mnem().lower()=='jmp' and graph[1][x]==[c]
  changes.append({'ea':x,'old_first_byte':'eb','new_first_byte':'90','original_path_bytes':ida_bytes.get_bytes(x,d-x).hex(),'target':c,'reason':'Replace JMP to own second byte with flag-preserving NOP, preserve alternate entry instruction bytes.'})
 journal={'body_index':ix,'start':a,'end':b,'original_bytes':ida_bytes.get_bytes(a,b-a).hex(),'sha256_before':hashlib.sha256(ida_bytes.get_bytes(a,b-a)).hexdigest(),'patches':changes}
 body_overlap_journals.append(journal)
 for p in changes:ida_bytes.patch_byte(p['ea'],0x90)
 return domain_flag_graph_v3(a,b)

